\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Climate/Ocean Color Theme ──
\definecolor{primary}{HTML}{0B3D5E}      % deep ocean blue
\definecolor{secondary}{HTML}{C2410C}     % warm terracotta
\definecolor{accent}{HTML}{DC2626}        % alert red
\definecolor{bgposter}{HTML}{F2F5F9}      % cool light gray-blue
\definecolor{redbg}{HTML}{FFF5F3}         % warm pink tint
\definecolor{bluebg}{HTML}{F0F4FF}        % cool blue tint
\definecolor{darkbg}{HTML}{EEF2F7}        % cool ocean tint
\definecolor{redtitlebg}{HTML}{FDEAE8}    % red card title bar
\definecolor{bluetitlebg}{HTML}{E4ECFF}   % blue card title bar
\definecolor{darktitlebg}{HTML}{E0EAF3}   % dark card title bar
\definecolor{textdark}{HTML}{111827}
\definecolor{textgray}{HTML}{4B5563}
\definecolor{stathighlight}{HTML}{F0F8FF}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=28pt, itemsep=10pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=28pt, itemsep=10pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redtitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=bluetitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  darkcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=darkbg,
    borderline west={5pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=darktitlebg,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={primary!50},
    valign=top, drop shadow={opacity=0.18},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!15!white,
    borderline west={6pt}{0pt}{primary},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=6pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.22},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ═══════════════════════════════════════════════════════════════
% TITLE BAR  (rows 1–4, span=3)
% ═══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=14pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{76}{92}\selectfont\bfseries 300 Years of Sclerosponge Thermometry}\\[10pt]
  {\fontsize{68}{82}\selectfont\bfseries Shows Global Warming Has Exceeded 1.5 °C}\\[16pt]
  {\fontsize{38}{46}\selectfont McCulloch~M.\textsuperscript{1,2}, Winter~A.\textsuperscript{3},
   Sherman~C.\textsuperscript{4}~\& Trotter~J.\textsuperscript{1}}\\[10pt]
  {\fontsize{30}{38}\selectfont\color{white!70}
   \textsuperscript{1}University of Western Australia \quad
   \textsuperscript{2}ARC Centre of Excellence for Coral Reef Studies \quad
   \textsuperscript{3}Fairleigh Dickinson University \quad
   \textsuperscript{4}University of Puerto Rico}\\[6pt]
  {\fontsize{28}{34}\selectfont\color{white!60}
   \textit{Nature Climate Change}, 2024 \quad$\bullet$\quad
   AGU / Nature Climate Change Symposium}
}

% ═══════════════════════════════════════════════════════════════
% STATS BANNER  (rows 4–6, span=3)
% ═══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!12!white, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=4pt, bottom=4pt,
  valign=center, borderline south={3pt}{0pt}{primary!35},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary}$\sim$300}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdark}Record Length (years)}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary!40}{redbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{secondary}$\sim$0.5\,°C}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdark}Hidden Pre-Industrial Warming}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accent!50}{redbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{accent}>1.5\,°C}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdark}Total Warming Exceeded}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{60}{72}\selectfont\bfseries\color{primary}$\sim$1.2\,°C}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdark}IPCC-Reported Warming}\vspace{8pt}%
    }}
  \end{minipage}
}

% ═══════════════════════════════════════════════════════════════
% ROW BAND A  (rows 6–12)
% ═══════════════════════════════════════════════════════════════

% Col 1: Why Sclerosponges?
\posterbox[redcard, title={Why Sclerosponges?}]
  {name=background, column=1, between=row6 and row12}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}[itemsep=12pt]
    \item Long-lived marine organisms in tropical \& subtropical oceans
    \item Sr/Ca ratios in aragonite skeletons faithfully track ambient SST
    \item Continuous growth $\to$ unbroken annual-resolution records to $\sim$1700~CE
    \item Independent of instrumental networks, which only begin $\sim$1850
    \item Caribbean specimens collected at 33--91\,m depth
  \end{itemize}
  \vspace{4pt}
  \colorbox{secondary!18}{\parbox{0.92\linewidth}{%
    \centering\fontsize{30}{38}\selectfont
    \textbf{Key advantage:} Extends reliable SST record \\ 150 years before the earliest thermometers
  }}
}

% Col 2–3 (span=2): Hero Figure — 300-Year Temperature Reconstruction
\posterbox[bluecard, title={300-Year Temperature Reconstruction}]
  {name=timeline, column=2, span=2, between=row6 and row12}{
  \vspace{-2pt}
  \posterfig{0.98}{figures/temperature_timeline.png}{%
    Sr/Ca-derived SST anomaly reconstruction (1700--2020) with HadCRUT5 instrumental overlay.
    Red dashed line marks the Paris Agreement 1.5\,°C threshold, crossed in the early 2020s.}
  \vspace{2pt}
  \begin{center}
  \colorbox{accent!18}{\parbox{0.94\linewidth}{%
    \centering\fontsize{32}{40}\selectfont\bfseries\color{accent}
    The 1.5\,°C Paris target has already been surpassed when measured against a true pre-industrial baseline.
  }}
  \end{center}
}

% ═══════════════════════════════════════════════════════════════
% ROW BAND B  (rows 12–17)
% ═══════════════════════════════════════════════════════════════

% Col 1: Pre-Industrial Baseline Matters
\posterbox[darkcard, title={Pre-Industrial Baseline Matters}]
  {name=baseline, column=1, between=row12 and row17}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}[itemsep=12pt]
    \item IPCC operationally uses 1850--1900 as ``pre-industrial'' reference
    \item Sclerosponge data reveal this period was \textbf{already $\sim$0.5\,°C} above the 1700--1790 mean
    \item Early industrialization (1790--1850) drove detectable warming before instrumental records began
    \item The ``pre-industrial'' label for 1850--1900 systematically underestimates total anthropogenic warming
  \end{itemize}
  \vspace{4pt}
  \colorbox{primary!18}{\parbox{0.92\linewidth}{%
    \centering\fontsize{30}{38}\selectfont
    \textbf{Total warming: $\sim$1.7\,°C} (true baseline) \\ vs. \textbf{$\sim$1.2\,°C} (IPCC baseline)
  }}
}

% Col 2: Data \& Methods
\posterbox[bluecard, title={Data \& Methods}]
  {name=methods, column=2, between=row12 and row17}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}[itemsep=12pt]
    \item Sclerosponge specimens from Caribbean reefs at 33--91\,m depth
    \item Sr/Ca ratios measured via \textbf{ICP-OES} (inductively coupled plasma optical emission spectrometry)
    \item Calibrated against co-located instrumental SST records (r$^2$ $>$ 0.9, 1960--present)
    \item Reconstruction validated against HadCRUT5 \& NOAA ERSSTv5
    \item Excellent agreement in instrumental era; divergence only pre-1850
  \end{itemize}
  \vspace{4pt}
  \colorbox{primary!18}{\parbox{0.92\linewidth}{%
    \centering\fontsize{30}{38}\selectfont
    $\displaystyle \frac{\mathrm{Sr}}{\mathrm{Ca}} = a + b \cdot \mathrm{SST}$\quad (r$^2$ $>$ 0.9)
  }}
}

% Col 3: Warming Comparison Chart
\posterbox[bluecard, title={The Hidden 0.5\,°C}]
  {name=comparison, column=3, between=row12 and row17}{
  \vspace{-2pt}
  \posterfig{0.94}{figures/warming_comparison.png}{%
    Total warming differs by $\sim$0.5\,°C depending on baseline choice.
    The sclerosponge-informed baseline reveals that the Paris 1.5\,°C target has been exceeded.}
  \vspace{2pt}
  \begin{center}
  \colorbox{secondary!18}{\parbox{0.92\linewidth}{%
    \centering\fontsize{30}{38}\selectfont
    \textbf{$\sim$0.5\,°C of warming occurred before} \\ \textbf{the instrumental record even begins.}
  }}
  \end{center}
}

% ═══════════════════════════════════════════════════════════════
% ROW BAND C  (rows 17–20)
% ═══════════════════════════════════════════════════════════════

% Col 1: Policy Implications
\posterbox[redcard, title={Policy \& Carbon Budget Implications}]
  {name=policy, column=1, between=row17 and bottom}{
  \fontsize{34}{44}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item Paris 1.5\,°C target \textbf{already exceeded} under true pre-industrial baseline
    \item Remaining carbon budget for 1.5\,°C: effectively \textbf{zero}
  \end{itemize}
  \vspace{4pt}
  \colorbox{secondary!18}{\parbox{0.92\linewidth}{%
    \centering\fontsize{30}{38}\selectfont
    2.0\,°C guardrail: \textbf{$\sim$0.3\,°C} remaining \\ (vs. $\sim$0.8\,°C previously estimated)
  }}
  \vspace{4pt}
  \begin{itemize}[itemsep=10pt]
    \item Urgency of rapid emissions reductions is \textbf{greater than previously assessed}
    \item Transparent communication about how baselines affect perceived climate targets is essential
  \end{itemize}
}

% Col 2: References
\posterbox[redcard, title={Key References}]
  {name=references, column=2, between=row17 and bottom}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item McCulloch~M.\textit{ et al.} (2024). 300 years of sclerosponge thermometry shows global warming has exceeded 1.5\,°C. \textit{Nature Climate Change.}
    \item IPCC (2021). AR6 WG1: The Physical Science Basis. Contribution of WG1 to the Sixth Assessment Report.
    \item Morice~C.P.\textit{ et al.} (2021). An updated assessment of near-surface temperature change from 1850: HadCRUT5. \textit{JGR Atmospheres.}
    \item Huang~B.\textit{ et al.} (2017). Extended Reconstructed SST version~5 (ERSSTv5). \textit{Journal of Climate.}
  \end{itemize}
  \vspace{4pt}
  \colorbox{primary!18}{\parbox{0.92\linewidth}{%
    \centering\fontsize{28}{34}\selectfont
    \textbf{Data \& Code:} github.com/climate-sclerosponge
  }}
}

% Col 3: Key Takeaways
\posterbox[highlightcard, title={Key Takeaways}]
  {name=takeaways, column=3, between=row17 and bottom}{
  \fontsize{34}{44}\selectfont\color{textdark}
  \begin{itemize}[itemsep=14pt, label={\color{white}$\blacktriangleright$}]
    \item Sclerosponge proxies extend the climate record \textbf{150 years before} instrumental measurements
    \item The true pre-industrial baseline (1700--1790) reveals \textbf{$\sim$0.5\,°C of hidden warming} by 1850--1900
    \item The Paris Agreement \textbf{1.5\,°C threshold has already been crossed}
    \item \textbf{Baselines matter:} policy targets and carbon budgets depend critically on the reference period chosen
  \end{itemize}
}

\end{tcbposter}
\end{document}

